-- =========================================================================
-- Tarwiza (ترويئة) - Database Seeding Script (Menu Items with Details)
-- Matches Layer-Based Clean Architecture Data Model
-- Run this script in the Supabase SQL Editor
-- =========================================================================

-- Enable UUID extension if not enabled
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Start Transaction
BEGIN;

-- ==========================================
-- 1. SEED CATEGORIES (with static UUIDs)
-- ==========================================

ON CONFLICT (id) DO UPDATE SET 
  name = EXCLUDED.name,
  name_ar = EXCLUDED.name_ar,
  sort_order = EXCLUDED.sort_order;


-- ==========================================
-- 2. SEED PRODUCTS (with static UUIDs & descriptions)
-- ==========================================

-- Category 1: Soups (الشوربة)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 2: Various Dishes (أطباق متنوعة)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 3: Pans (الطاسات)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 4: Crepes (الكريب)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 5: Pizza (البيتزا)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 6: Sandwiches (الساندوتش)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 7: Hawawshi (حواوشي)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 8: Syrian Sandwiches (سندوتشات سوري)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 9: Pasta (المعكرونات والمعجنات)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 10: Rizo (ريزو)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 11: Grills (المشويات)
-- We store base price as 1/4 chicken or 1/8 kg of grills.
-- Grills descriptions specify standard side items.
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 12: Meals (الوجبات)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 13: Add-ons (الإضافات)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;

-- Category 14: Desserts (الحلو)
ON CONFLICT (id) DO UPDATE SET price = EXCLUDED.price, name_ar = EXCLUDED.name_ar, description = EXCLUDED.description, description_ar = EXCLUDED.description_ar;


